INSERT INTO _migration_488_expected (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_igbio_cells_s2_001', 'topic_igcse_bio_cells', 'subj_igcse_biology', 'igcse', NULL, NULL, 'Which cell structure is present in a plant cell but absent from an animal cell?', 'multiple_choice', NULL, '["A. Cell wall","B. Cell membrane","C. Cytoplasm","D. Mitochondrion"]', 'A', 'Plant cells have a cellulose cell wall, chloroplasts and a large permanent vacuole in addition to the structures they share with animal cells. The cell membrane, cytoplasm and mitochondria are found in both cell types, so none of them can distinguish a plant cell from an animal cell. Therefore the correct answer is A: Cell wall.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_cambridge'),
('q_igbio_cells_s2_002', 'topic_igcse_bio_cells', 'subj_igcse_biology', 'igcse', NULL, NULL, 'A student''s drawing of a cell is 45 mm long. The actual cell is 0.15 mm long. What is the magnification of the drawing?', 'multiple_choice', NULL, '["A. ×30","B. ×300","C. ×6.75","D. ×3000"]', 'B', 'Magnification = image size ÷ actual size = 45 mm ÷ 0.15 mm = 300, so the drawing is ×300 the size of the real cell. ×30 comes from a slip in the division, ×6.75 results from multiplying instead of dividing (45 × 0.15), and ×3000 comes from misplacing the decimal point. Therefore the correct answer is B: ×300.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, 'board_cambridge'),
('q_igbio_cells_s2_003', 'topic_igcse_bio_cells', 'subj_igcse_biology', 'igcse', NULL, NULL, 'A microscope has an eyepiece lens of ×10 and objective lenses of ×4, ×10 and ×40. Which combination gives a total magnification of ×400?', 'multiple_choice', NULL, '["A. Eyepiece ×10 with objective ×4","B. Eyepiece ×10 with objective ×10","C. Eyepiece ×10 with objective ×40","D. Objective ×40 alone without the eyepiece"]', 'C', 'Total magnification = eyepiece magnification × objective magnification = 10 × 40 = 400. The ×4 objective gives only ×40 and the ×10 objective gives ×100, and a light microscope image is always viewed through the eyepiece, so the objective cannot be used alone. Therefore the correct answer is C: Eyepiece ×10 with objective ×40.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Apply', 'AO2', NULL, NULL, 'board_cambridge'),
('q_igbio_cells_s2_004', 'topic_igcse_bio_cells', 'subj_igcse_biology', 'igcse', NULL, NULL, 'A student viewing a slide under high power finds the image blurry. Which part of the microscope should the student adjust to make the image sharp?', 'multiple_choice', NULL, '["A. The coarse adjustment knob","B. The mirror, to admit more light","C. The eyepiece, changing it for a higher-power lens","D. The fine adjustment knob"]', 'D', 'At high power only the fine adjustment knob should be used to focus, because the objective lens is very close to the slide and the coarse knob could drive the lens into the slide. The mirror or lamp changes brightness rather than sharpness, and swapping the eyepiece changes magnification without focusing the image. Therefore the correct answer is D: The fine adjustment knob.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Apply', 'AO2', NULL, NULL, 'board_cambridge'),
('q_igbio_cells_s2_005', 'topic_igcse_bio_cells', 'subj_igcse_biology', 'igcse', NULL, NULL, 'Root hair cells absorb water from the soil efficiently. Which feature of a root hair cell increases the surface area available for absorption?', 'multiple_choice', NULL, '["A. A long hair-like projection extending into the soil","B. A thick cellulose cell wall","C. A large number of chloroplasts","D. A permanent vacuole filled with starch grains"]', 'A', 'The root hair is a slender extension of the cell that greatly increases the surface area to volume ratio for the absorption of water and mineral ions. Root hair cells grow underground so they contain no chloroplasts, their cell wall stays thin to let water pass, and the vacuole holds cell sap rather than starch grains. Therefore the correct answer is A: A long hair-like projection extending into the soil.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Apply', 'AO2', NULL, NULL, 'board_cambridge'),
('q_igbio_cells_s2_006', 'topic_igcse_bio_cells', 'subj_igcse_biology', 'igcse', NULL, NULL, 'Which row correctly matches a specialised animal cell with its adaptation?', 'multiple_choice', NULL, '["A. Red blood cell — has a large nucleus to store more DNA","B. Ciliated cell — has cilia that beat to move mucus along the airways","C. Muscle cell — contains chloroplasts to release energy","D. Nerve cell — has a thick cell wall for protection"]', 'B', 'Ciliated cells line the trachea and bronchi, and their beating cilia move mucus carrying trapped particles away from the lungs. Red blood cells lose their nucleus so they can carry more haemoglobin, animal cells never contain chloroplasts, and cell walls occur in plant cells, not in nerve cells. Therefore the correct answer is B: Ciliated cell — has cilia that beat to move mucus along the airways.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_cambridge');
INSERT INTO _migration_488_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM _migration_488_expected e JOIN questions q ON q.id = e.id WHERE NOT (q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id)) AND NOT EXISTS (SELECT 1 FROM _migration_488_expected e JOIN question_content_releases r ON r.question_id = e.id WHERE NOT (r.batch_id IS 'igcse-bio-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Biology (0610) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-biology-0610/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) SELECT id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id FROM _migration_488_expected e WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = e.id);
INSERT INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT e.id, 'igcse-bio-sprint2-001', 'automated_beta', 'beta', 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Biology (0610) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.', 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-biology-0610/', 0, 1 FROM _migration_488_expected e WHERE NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = e.id);
INSERT INTO _migration_488_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions q JOIN _migration_488_expected e ON e.id = q.id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id) = 6 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _migration_488_expected e ON e.id = r.question_id WHERE r.batch_id IS 'igcse-bio-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Biology (0610) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-biology-0610/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 6 AND (SELECT COUNT(*) FROM questions q JOIN topics t ON t.id = q.topic_id AND t.subject_id = q.subject_id JOIN _migration_488_expected e ON e.id = q.id) = 6 THEN 1 ELSE 0 END;
